// This file was generated by Prisma and assumes you have installed the following:
import 'dotenv/config'
import { defineConfig, env } from 'prisma/config'

// Neon's pooled (PgBouncer) endpoint can't reliably acquire the Postgres
// advisory lock that Prisma Migrate takes, which surfaces as P1002 timeouts.
// Migrations must run against the direct (unpooled) endpoint instead. Prefer an
// explicit DIRECT_URL, but fall back to deriving it from DATABASE_URL by
// dropping the "-pooler" host segment so older .env files keep working.
// `||` rather than `??`: .env.example ships DIRECT_URL empty, and an empty
// string is not nullish — it would otherwise become the direct URL.
const directUrl = process.env.DIRECT_URL || process.env.DATABASE_URL?.replace('-pooler', '')

export default defineConfig({
  schema: 'prisma/schema.prisma',
  migrations: {
    // A production deploy points this at a copy without the contract migrations that must wait.
    path: process.env.PRISMA_MIGRATIONS_PATH || 'prisma/migrations'
  },
  datasource: {
    url: env('DATABASE_URL'),
    directUrl: directUrl ?? env('DIRECT_URL'),
    // Local PGlite servers ship a second database for migrate's shadow, so
    // `migrate dev` can author migrations without reaching for Neon. Neon and
    // CI leave this unset and let Prisma provision a shadow database itself.
    ...(process.env.SHADOW_DATABASE_URL ? { shadowDatabaseUrl: process.env.SHADOW_DATABASE_URL } : {})
  }
})
